from solution import opposite_Signs
import inspect


def test_issue_example_1_minus2():
    """Check example opposite_Signs(1,-2) == True."""
    assert opposite_Signs(1, -2) == True  # 1>0 and -2<0 => True


def test_issue_negative_positive():
    """Check opposite signs with negative first returns True."""
    assert opposite_Signs(-5, 10) == True  # -5<0 and 10>0 => True


def test_issue_both_positive():
    """Check same positive signs returns False."""
    assert opposite_Signs(3, 7) == False  # 3>0 and 7>0 => False


def test_issue_both_negative():
    """Check same negative signs returns False."""
    assert opposite_Signs(-3, -7) == False  # -3<0 and -7<0 => False


def test_issue_zero_and_positive():
    """Check zero and positive are not opposite signs."""
    assert opposite_Signs(0, 5) == False  # 0==0 so no opposite => False


def test_issue_zero_and_negative():
    """Check zero and negative are not opposite signs."""
    assert opposite_Signs(0, -5) == False  # 0==0 so no opposite => False


def test_issue_both_zero():
    """Check zero and zero are not opposite signs."""
    assert opposite_Signs(0, 0) == False  # 0==0 and 0==0 => False


def test_issue_one_and_minus_one():
    """Check boundary values 1 and -1 are opposite signs."""
    assert opposite_Signs(1, -1) == True  # 1>0 and -1<0 => True


def test_issue_large_opposite():
    """Check large magnitudes with opposite signs returns True."""
    assert opposite_Signs(1000000, -1000000) == True  # 1000000>0 and -1000000<0 => True


def test_issue_large_same_sign():
    """Check large magnitudes with same sign returns False."""
    assert opposite_Signs(-1000000, -999999) == False  # -1000000<0 and -999999<0 => False


def test_contract_callable():
    """Check opposite_Signs is callable in solution module."""
    assert callable(opposite_Signs) == True  # callable function => True


def test_contract_signature():
    """Check opposite_Signs takes parameters x and y."""
    assert list(inspect.signature(opposite_Signs).parameters.keys()) == ["x", "y"]  # params x,y => ["x", "y"]
